 chunks.append(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"voice\"; filename=\"practice.mp3\"\r\nContent-Type: audio/mpeg\r\n\r\n").encode()+audio+b"\r\n")
 chunks.append(("--"+boundary+"--\r\n").encode())
